            rec["B"],
            rec["C"],
            rec["D"],
            rec["E"],
            rec["F"],
            rec["G"],
            rec["H"],
        ]

        for c, val in enumerate(row_values, start=1):
            cell = ws.cell(row=out_r, column=c)
            cell.value = val

            if c in (4, 5, 6):
                f = copy(cell.font)
                f.bold = True
                cell.font = f

                a = copy(cell.alignment)
                a.horizontal = "center"
                a.vertical = "center"
                cell.alignment = a

                if isinstance(val, (int, float)) and not isinstance(val, bool):
                    if float(val).is_integer():
                        cell.number_format = "0"
                    else:
                        cell.number_format = "0.0"

        out_r += 1

    if bi != len(sorted_blocks) - 1:
        for c in range(1, COLS + 1):
            ws.cell(row=out_r, column=c).value = None
        out_r += 1

try:
    wb.calculation.fullCalcOnLoad = True
except Exception:
    pass

wb.save(OUT)

print("blocks:", len(blocks))
print("data_rows:", sum(len(b) for b in blocks))
print("last_out_row:", out_r - 1)
if out_r > 1:
    print("A1:", ws["A1"].value, "D1:", ws["D1"].value, "F1:", ws["F1"].value)
